
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_vt84_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_vt84", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.787807134354995e+00, -4.690776912929917e+00, -4.554735264419469e+00, -4.366120494502963e+00, -4.108774802729434e+00, -3.765606600514702e+00, -3.322737886352357e+00, -2.777661437282660e+00, -2.153724518732420e+00, -1.522604352699934e+00, -9.910575042756652e-01, -6.877827696317024e-01, -5.995337099355185e-01, -5.072981558577232e-01, -3.606630213183973e-01, -2.219585676100367e-01, -1.279492186108443e-01, -4.873241987543965e-02, -5.710786780318357e-03, -2.529442476068709e-05]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


